const std = @import("std"); const mem2 = std.mem; const fla2 = std.compress.flate;
const CF = .{ .objz = 60000, .infz = 16 << 20, .totz = 128 << 20, .rati = 1000, .slak = 1 << 20, .pair = 256, .osmx = 30000 };
pub const Pair = struct { key2: []const u8, val2: []const u8 };
pub const Docz = struct { aren: std.mem.Allocator, tmpz: std.mem.Allocator, data: []const u8, objs: std.AutoHashMapUnmanaged(u32, []const u8) = .empty, budg: usize = CF.totz };
pub fn iszzWszz(byt2: u8) bool { return byt2 == 0 or byt2 == 9 or byt2 == 10 or byt2 == 12 or byt2 == 13 or byt2 == 32; }
pub fn iszzDelz(byt2: u8) bool { return mem2.findScalar(u8, "()<>[]{}/%", byt2) != null; }
pub fn skipWszz(srcz: []const u8, from: usize) usize { var kixz = from; while (kixz < srcz.len) { if (iszzWszz(srcz[kixz])) { kixz += 1; } else if (srcz[kixz] == '%') { while (kixz < srcz.len and srcz[kixz] != '\n' and srcz[kixz] != '\r') kixz += 1; } else break; } return kixz; }
fn strzEndz(srcz: []const u8, from: usize) usize { var kixz = from + 1; var depz: usize = 1; while (kixz < srcz.len) : (kixz += 1) { if (srcz[kixz] == '\\') { kixz += 1; } else if (srcz[kixz] == '(') { depz += 1; } else if (srcz[kixz] == ')') { depz -= 1; if (depz == 0) return kixz + 1; } } return srcz.len; }
fn refzEndz(srcz: []const u8, from: usize) ?usize { var kixz = from; while (kixz < srcz.len and std.ascii.isDigit(srcz[kixz])) kixz += 1; if (kixz == from) return null; const aaa2 = kixz; while (kixz < srcz.len and iszzWszz(srcz[kixz])) kixz += 1; if (kixz == aaa2) return null; const bbbz = kixz; while (kixz < srcz.len and std.ascii.isDigit(srcz[kixz])) kixz += 1; if (kixz == bbbz) return null; const cccz = kixz; while (kixz < srcz.len and iszzWszz(srcz[kixz])) kixz += 1; if (kixz == cccz or kixz >= srcz.len or srcz[kixz] != 'R') return null; kixz += 1; if (kixz < srcz.len and !iszzWszz(srcz[kixz]) and !iszzDelz(srcz[kixz])) return null; return kixz; }
pub fn valuEndz(srcz: []const u8, from: usize) usize { if (from >= srcz.len) return srcz.len; const chr2 = srcz[from]; var kixz = from; if (chr2 == '<' and from + 1 < srcz.len and srcz[from + 1] == '<') { var depz: usize = 0; while (kixz + 1 < srcz.len) { if (srcz[kixz] == '<' and srcz[kixz + 1] == '<') { depz += 1; kixz += 2; } else if (srcz[kixz] == '>' and srcz[kixz + 1] == '>') { depz -= 1; kixz += 2; if (depz == 0) return kixz; } else if (srcz[kixz] == '(') { kixz = strzEndz(srcz, kixz); } else kixz += 1; } return srcz.len; } if (chr2 == '<') return (mem2.findScalarPos(u8, srcz, from, '>') orelse srcz.len - 1) + 1; if (chr2 == '(') return strzEndz(srcz, from); if (chr2 == '[') { var depz: usize = 0; while (kixz < srcz.len) { if (srcz[kixz] == '[') { depz += 1; kixz += 1; } else if (srcz[kixz] == ']') { depz -= 1; kixz += 1; if (depz == 0) return kixz; } else if (srcz[kixz] == '(') { kixz = strzEndz(srcz, kixz); } else kixz += 1; } return srcz.len; } if (chr2 == '/') { kixz += 1; while (kixz < srcz.len and !iszzWszz(srcz[kixz]) and !iszzDelz(srcz[kixz])) kixz += 1; return kixz; } if (refzEndz(srcz, from)) |rend| return rend; while (kixz < srcz.len and !iszzWszz(srcz[kixz]) and !iszzDelz(srcz[kixz])) kixz += 1; return @max(kixz, from + 1); }
pub fn dictPair(aren: std.mem.Allocator, body: []const u8) ![]Pair { const begz = mem2.find(u8, body, "<<") orelse return &.{}; var list: std.ArrayList(Pair) = .empty; var kixz = begz + 2; while (list.items.len < CF.pair) { kixz = skipWszz(body, kixz); if (kixz >= body.len or body[kixz] != '/') break; const kstz = kixz + 1; var kenz = kstz; while (kenz < body.len and !iszzWszz(body[kenz]) and !iszzDelz(body[kenz])) kenz += 1; kixz = skipWszz(body, kenz); if (kixz >= body.len) break; const venz = valuEndz(body, kixz); try list.append(aren, .{ .key2 = body[kstz..kenz], .val2 = body[kixz..venz] }); kixz = venz; } return list.toOwnedSlice(aren); }
pub fn pairGetz(pszz: []const Pair, key2: []const u8) ?[]const u8 { for (pszz) |pair| if (mem2.eql(u8, pair.key2, key2)) return pair.val2; return null; }
pub fn refzOfzz(val2: []const u8) ?u32 { const trmz = mem2.trim(u8, val2, " \t\r\n"); const rend = refzEndz(trmz, 0) orelse return null; if (rend != trmz.len) return null; var kixz: usize = 0; while (kixz < trmz.len and std.ascii.isDigit(trmz[kixz])) kixz += 1; return std.fmt.parseInt(u32, trmz[0..kixz], 10) catch null; }
pub fn intzOfzz(val2: []const u8) ?i64 { return std.fmt.parseInt(i64, mem2.trim(u8, val2, " \t\r\n"), 10) catch null; }
fn enczFlag(data: []const u8) bool { var kixz: usize = 0; while (mem2.findPos(u8, data, kixz, "/Encrypt")) |hitz| { kixz = hitz + 8; if (kixz < data.len and (iszzWszz(data[kixz]) or data[kixz] == '<' or std.ascii.isDigit(data[kixz]))) return true; } return false; }
pub fn doczOpen(aren: std.mem.Allocator, tmpz: std.mem.Allocator, data: []const u8) !Docz { if (mem2.find(u8, data[0..@min(data.len, 1024)], "%PDF-") == null) return error.BadPdf; if (enczFlag(data)) return error.Encrypted; var docz: Docz = .{ .aren = aren, .tmpz = tmpz, .data = data }; var kixz: usize = 0; while (mem2.findPos(u8, data, kixz, "obj")) |hitz| { kixz = hitz + 3; if (hitz < 4 or (hitz >= 3 and mem2.eql(u8, data[hitz - 3 .. hitz], "end"))) continue; if (kixz < data.len and std.ascii.isAlphabetic(data[kixz])) continue; var jixz = hitz; while (jixz > 0 and iszzWszz(data[jixz - 1])) jixz -= 1; const genz = jixz; while (jixz > 0 and std.ascii.isDigit(data[jixz - 1])) jixz -= 1; if (jixz == genz) continue; const gstz = jixz; while (jixz > 0 and iszzWszz(data[jixz - 1])) jixz -= 1; if (jixz == gstz) continue; const nenz = jixz; while (jixz > 0 and std.ascii.isDigit(data[jixz - 1])) jixz -= 1; if (jixz == nenz) continue; const num2 = std.fmt.parseInt(u32, data[jixz..nenz], 10) catch continue; const endz = mem2.findPos(u8, data, kixz, "endobj") orelse data.len; if (docz.objs.count() >= CF.objz) return error.TooMany; try docz.objs.put(aren, num2, data[kixz..endz]); kixz = endz; } if (docz.objs.count() == 0) return error.BadPdf; try objzStms(&docz); return docz; }
pub fn streOfzz(docz: *Docz, body: []const u8) ![]const u8 { const spos = mem2.find(u8, body, "stream") orelse return error.NoStream; const pszz = try dictPair(docz.aren, body[0..spos]); var sttz = spos + 6; if (sttz < body.len and body[sttz] == '\r') sttz += 1; if (sttz < body.len and body[sttz] == '\n') sttz += 1; var ennz = mem2.findLast(u8, body, "endstream") orelse body.len; if (ennz < sttz) ennz = sttz; var rawz = body[sttz..ennz]; if (pairGetz(pszz, "Length")) |lenv| { if (intzOfzz(lenv)) |lenz| { if (lenz >= 0 and sttz + @as(usize, @intCast(lenz)) <= ennz) rawz = body[sttz .. sttz + @as(usize, @intCast(lenz))]; } else { while (rawz.len > 0 and (rawz[rawz.len - 1] == '\n' or rawz[rawz.len - 1] == '\r')) rawz = rawz[0 .. rawz.len - 1]; } } const filt = pairGetz(pszz, "Filter") orelse return rawz; if (mem2.find(u8, filt, "FlateDecode") == null and mem2.find(u8, filt, "/Fl") == null) return error.Unsupported; if (mem2.count(u8, filt, "/") > 1) return error.Unsupported; const limz = @min(@min(CF.infz, docz.budg), rawz.len * CF.rati + CF.slak); var inpt = std.Io.Reader.fixed(rawz); const wind = try docz.tmpz.alloc(u8, fla2.max_window_len); defer docz.tmpz.free(wind); var deco = fla2.Decompress.init(&inpt, .zlib, wind); const outp = deco.reader.allocRemaining(docz.tmpz, .limited(limz)) catch |err3| switch (err3) { error.StreamTooLong => return error.Bomb, else => return error.BadStream }; defer docz.tmpz.free(outp); if (outp.len > docz.budg) return error.Bomb; docz.budg -= outp.len; return docz.aren.dupe(u8, outp); }
fn objzStms(docz: *Docz) !void { var nums: std.ArrayList(u32) = .empty; defer nums.deinit(docz.tmpz); var iter = docz.objs.iterator(); while (iter.next()) |entr| { if (mem2.find(u8, entr.value_ptr.*[0..@min(entr.value_ptr.len, 400)], "/ObjStm") != null) try nums.append(docz.tmpz, entr.key_ptr.*); } for (nums.items) |num2| { const body = docz.objs.get(num2).?; const spos = mem2.find(u8, body, "stream") orelse continue; const pszz = try dictPair(docz.aren, body[0..spos]); const con2 = intzOfzz(pairGetz(pszz, "N") orelse continue) orelse continue; const fstz = intzOfzz(pairGetz(pszz, "First") orelse continue) orelse continue; if (con2 < 1 or con2 > CF.osmx or fstz < 0) continue; const decz = streOfzz(docz, body) catch continue; var hdr3 = mem2.tokenizeAny(u8, decz[0..@min(decz.len, @as(usize, @intCast(fstz)))], " \t\r\n"); var idsz: std.ArrayList(u32) = .empty; defer idsz.deinit(docz.tmpz); var offs: std.ArrayList(usize) = .empty; defer offs.deinit(docz.tmpz); var kixz: i64 = 0; while (kixz < con2) : (kixz += 1) { const idtz = hdr3.next() orelse break; const oftz = hdr3.next() orelse break; const idvz = std.fmt.parseInt(u32, idtz, 10) catch break; const ofvz = std.fmt.parseInt(usize, oftz, 10) catch break; try idsz.append(docz.tmpz, idvz); try offs.append(docz.tmpz, ofvz); } for (idsz.items, 0..) |oidz, ind2| { const bstz = @as(usize, @intCast(fstz)) + offs.items[ind2]; const benz = if (ind2 + 1 < offs.items.len) @as(usize, @intCast(fstz)) + offs.items[ind2 + 1] else decz.len; if (bstz > benz or benz > decz.len) continue; if (!docz.objs.contains(oidz)) try docz.objs.put(docz.aren, oidz, decz[bstz..benz]); } } }
